<?php require 'config.php';require_login();$s=$pdo->prepare("SELECT * FROM bookings WHERE id=? AND user_id=? AND status='CONFIRMED'");$s->execute([(int)$_GET['id'],$_SESSION['user_id']]);$b=$s->fetch();if($b){$pdo->beginTransaction();$pdo->prepare("UPDATE bookings SET status='CANCELLED' WHERE id=?")->execute([$b['id']]);$pdo->prepare('UPDATE flights SET available_seats=available_seats+1 WHERE id=?')->execute([$b['flight_id']]);$pdo->commit();}header('Location: my_tickets.php');exit;?>